let whereobj = {
  "type":"and",
  "value": []
};

if (msg.topics.length > 0) {
  whereobj.value.push({"type": "in", 
                       "attribute": "topicId", 
                       "value": msg.topics});
};

if (msg.specId.length > 0) {
  whereobj.value.push({
    "type": "equals",
    "attribute": "specialtyId",
    "value": msg.specId
  });
};

msg.payload = {
    where : '[' + JSON.stringify(whereobj) + ']'
};

msg.headers = { "Authorization": "Bearer " + msg.authToken };

return msg;

msg.payload = {   "id" : msg.payload.id,
                  "topic" : msg.payload.topicName,
                  "sequence" : msg.payload.sequence.toString().padStart(5,"0"),
                  "question" : msg.payload.texto, 
                  "verification" : msg.payload.verification,
                  "reference" : msg.payload.normativas.reduce((accu, actual) => { return accu + actual.reglamentoName + " " + actual.name + "\n"}, "")
                };
return msg;

const specJson = JSON.parse(msg.payload);
msg.specId = specJson.list[0].id;
return msg;

let whereobj = {
  "type":"and",
  "value": []
};

let condition;

for (const [key, value] of Object.entries(msg.entityData)) {
  condition = {"type": (Array.isArray(value) ? "in" : "equals"),
               "attribute": key,
               "value" : value
              }

  whereobj.value.push(condition);
};

msg.payload = {
    where : '[' + JSON.stringify(whereobj) + ']'
};

msg.headers = { "Authorization": "Bearer " + msg.authToken };

return msg;
